CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

// Stage 1: conv(1->6, 5x5, valid) + ReLU + maxpool(2x2, stride=2)
// Input:  (N, 1, 32, 32)
// Output: (N, 6, 14, 14)
// Each thread computes one pooled output element at (n, oc, ph, pw)
__global__ __launch_bounds__(256, 4)
void lenet5_stage1_kernel(
    const float* __restrict__ input,   // (N, 1, 32, 32)
    const float* __restrict__ weight,  // (6, 1, 5, 5)
    const float* __restrict__ bias,    // (6,)
    float* __restrict__ output,        // (N, 6, 14, 14)
    int N
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * 6 * 14 * 14;
    if (idx >= total) return;

    int pw = idx % 14;
    int tmp = idx / 14;
    int ph = tmp % 14;
    tmp = tmp / 14;
    int oc = tmp % 6;
    int n  = tmp / 6;

    float b = __ldg(&bias[oc]);

    // Preload the 6x6 input patch
    float patch[6][6];
    int base_r = 2 * ph;
    int base_c = 2 * pw;
    #pragma unroll
    for (int dr = 0; dr < 6; dr++) {
        #pragma unroll
        for (int dc = 0; dc < 6; dc++) {
            patch[dr][dc] = __ldg(&input[n * 1024 + (base_r + dr) * 32 + (base_c + dc)]);
        }
    }

    // Load 5x5 weight for this output channel
    float w[5][5];
    #pragma unroll
    for (int kh = 0; kh < 5; kh++) {
        #pragma unroll
        for (int kw = 0; kw < 5; kw++) {
            w[kh][kw] = __ldg(&weight[oc * 25 + kh * 5 + kw]);
        }
    }

    float pool_max = -1e38f;
    #pragma unroll
    for (int dr2 = 0; dr2 < 2; dr2++) {
        #pragma unroll
        for (int dc2 = 0; dc2 < 2; dc2++) {
            float acc = b;
            #pragma unroll
            for (int kh = 0; kh < 5; kh++) {
                #pragma unroll
                for (int kw = 0; kw < 5; kw++) {
                    acc += patch[dr2 + kh][dc2 + kw] * w[kh][kw];
                }
            }
            acc = acc > 0.f ? acc : 0.f;
            if (acc > pool_max) pool_max = acc;
        }
    }

    output[n * 6 * 196 + oc * 196 + ph * 14 + pw] = pool_max;
}

// Stage 2: conv(6->16, 5x5, valid) + ReLU + maxpool(2x2, stride=2)
// Input:  (N, 6, 14, 14)
// Output: (N, 16, 5, 5)
// Each thread computes one pooled output element at (n, oc, ph, pw)
// Register pressure reduced: weights loaded on-demand via __ldg, no local w[6][5][5] array.
__global__ __launch_bounds__(256, 4)
void lenet5_stage2_kernel(
    const float* __restrict__ input,   // (N, 6, 14, 14)
    const float* __restrict__ weight,  // (16, 6, 5, 5)
    const float* __restrict__ bias,    // (16,)
    float* __restrict__ output,        // (N, 16, 5, 5)
    int N
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * 16 * 5 * 5;
    if (idx >= total) return;

    int pw = idx % 5;
    int tmp = idx / 5;
    int ph = tmp % 5;
    tmp = tmp / 5;
    int oc = tmp % 16;
    int n  = tmp / 16;

    float b = __ldg(&bias[oc]);

    // Load 6-channel 6x6 input patch into registers
    float patch[6][6][6]; // [ic][dr][dc]
    int base_r = 2 * ph;
    int base_c = 2 * pw;
    int n_input_offset = n * 6 * 196;
    #pragma unroll
    for (int ic = 0; ic < 6; ic++) {
        int ic_offset = n_input_offset + ic * 196;
        #pragma unroll
        for (int dr = 0; dr < 6; dr++) {
            int row_offset = ic_offset + (base_r + dr) * 14 + base_c;
            #pragma unroll
            for (int dc = 0; dc < 6; dc++) {
                patch[ic][dr][dc] = __ldg(&input[row_offset + dc]);
            }
        }
    }

    // Compute 4 conv outputs for the 2x2 pool window.
    // Weights loaded on-demand to reduce register pressure.
    int oc_weight_base = oc * 150; // oc * 6 * 25
    float pool_max = -1e38f;
    #pragma unroll
    for (int dr2 = 0; dr2 < 2; dr2++) {
        #pragma unroll
        for (int dc2 = 0; dc2 < 2; dc2++) {
            float acc = b;
            #pragma unroll
            for (int ic = 0; ic < 6; ic++) {
                int ic_w_base = oc_weight_base + ic * 25;
                #pragma unroll
                for (int kh = 0; kh < 5; kh++) {
                    int kh_w_base = ic_w_base + kh * 5;
                    #pragma unroll
                    for (int kw = 0; kw < 5; kw++) {
                        acc += patch[ic][dr2 + kh][dc2 + kw] * __ldg(&weight[kh_w_base + kw]);
                    }
                }
            }
            acc = acc > 0.f ? acc : 0.f;
            if (acc > pool_max) pool_max = acc;
        }
    }

    output[n * 400 + oc * 25 + ph * 5 + pw] = pool_max;
}

torch::Tensor lenet5_stage1_forward(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias
) {
    int N = x.size(0);
    auto output = torch::empty({N, 6, 14, 14}, x.options());
    int total = N * 6 * 14 * 14;
