    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * 6 * 14 * 14;
    if (idx >= total) return;

    int pw = idx % 14;
    int tmp = idx / 14;
    int ph = tmp % 14;
    tmp = tmp / 14;
    int oc = tmp % 6;
    int n = tmp / 6;

    float b = __ldg(&bias[oc]);
    float patch[6][6];
    int base_r = 2 * ph;
    int base_c = 2 * pw;

    #pragma unroll
    for (int dr = 0; dr < 6; dr++) {
        #pragma unroll
        for (int dc = 0; dc < 6; dc++) {
            patch[dr][dc] = __ldg(&input[n * 1024 + (base_r + dr) * 32 + (base_c + dc)]);
        }
    }

    float w[5][5];
    #pragma unroll
    for (int kh = 0; kh < 5; kh++) {
        #pragma unroll
        for (int kw = 0; kw < 5; kw++) {
            w[kh][kw] = __ldg(&weight[oc * 25 + kh * 5 + kw]);
        }
    }

    float pool_max = -1e38f;
    #pragma unroll
    for (int dr2 = 0; dr2 < 2; dr2++) {
        #pragma unroll
        for (int dc2 = 0; dc2 < 2; dc2++) {
            float acc = b;
            #pragma unroll
            for (int kh = 0; kh < 5; kh++) {
                #pragma unroll
                for (int kw = 0; kw < 5; kw++) {
                    acc += patch[dr2 + kh][dc2 + kw] * w[kh][kw];
                }
            }
            acc = acc > 0.f ? acc : 0.f;
            if (acc > pool_max) pool_max = acc;
        }
    }

    output[n * 6 * 196 + oc * 196 + ph * 14 + pw] = pool_max;
}

__global__ __launch_bounds__(256, 4)
void lenet5_stage2_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = N * 16 * 5 * 5;
    if (idx >= total) return;

    int pw = idx % 5;
    int tmp = idx / 5;
    int ph = tmp % 5;
    tmp = tmp / 5;
    int oc = tmp % 16;
    int n = tmp / 16;

    float b = __ldg(&bias[oc]);
    float acc00 = b;
    float acc01 = b;
    float acc10 = b;
    float acc11 = b;

    int base_r = 2 * ph;
    int base_c = 2 * pw;
    int n_input_base = n * 6 * 196;
    int oc_weight_base = oc * 150;

    #pragma unroll
    for (int ic = 0; ic < 6; ic++) {
        int ic_offset = n_input_base + ic * 196 + base_r * 14 + base_c;
        int w_base = oc_weight_base + ic * 25;

        // Load 6 rows of 6 elements each as row buffers to avoid 6x6 patch array
        float row0[6], row1[6], row2[6], row3[6], row4[6], row5[6];
        #pragma unroll
        for (int dc = 0; dc < 6; dc++) {
            row0[dc] = __ldg(&input[ic_offset + dc]);
            row1[dc] = __ldg(&input[ic_offset + 14 + dc]);
            row2[dc] = __ldg(&input[ic_offset + 28 + dc]);
            row3[dc] = __ldg(&input[ic_offset + 42 + dc]);
            row4[dc] = __ldg(&input[ic_offset + 56 + dc]);
            row5[dc] = __ldg(&input[ic_offset + 70 + dc]);
        }

        // kh=0: rows 0,1 for acc00/acc01; rows 1,2 for acc10/acc11
        #pragma unroll
        for (int kw = 0; kw < 5; kw++) {
            float wv0 = __ldg(&weight[w_base + kw]);
            acc00 += row0[kw] * wv0;
            acc01 += row0[kw + 1] * wv0;
            acc10 += row1[kw] * wv0;
            acc11 += row1[kw + 1] * wv0;
        }
        #pragma unroll
        for (int kw = 0; kw < 5; kw++) {
            float wv1 = __ldg(&weight[w_base + 5 + kw]);
            acc00 += row1[kw] * wv1;
            acc01 += row1[kw + 1] * wv1;
            acc10 += row2[kw] * wv1;
            acc11 += row2[kw + 1] * wv1;
        }
        #pragma unroll
        for (int kw = 0; kw < 5; kw++) {
            float wv2 = __ldg(&weight[w_base + 10 + kw]);
            acc00 += row2[kw] * wv2;
            acc01 += row2[kw + 1] * wv2;
            acc10 += row3[kw] * wv2;
            acc11 += row3[kw + 1] * wv2;
        }
        #pragma unroll
        for (int kw = 0; kw < 5; kw++) {
            float wv3 = __ldg(&weight[w_base + 15 + kw]);
            acc00 += row3[kw] * wv3;
            acc01 += row3[kw + 1] * wv3;
            acc10 += row4[kw] * wv3;
            acc11 += row4[kw + 1] * wv3;
        }
        #pragma unroll
        for (int kw = 0; kw < 5; kw++) {
            float wv4 = __ldg(&weight[w_base + 20 + kw]);
            acc00 += row4[kw] * wv4;
            acc01 += row4[kw + 1] * wv4;
            acc10 += row5[kw] * wv4;
            acc11 += row5[kw + 1] * wv4;
        }
    }

    acc00 = acc00 > 0.f ? acc00 : 0.f;
    acc01 = acc01 > 0.f ? acc01 : 0.f;
    acc10 = acc10 > 0.f ? acc10 : 0.f;
    acc11 = acc11 > 0.f ? acc11 : 0.f;

    float pool_max = acc00;
    if (acc01 > pool_max) pool_max = acc01;
    if (acc10 > pool_max) pool_max = acc10;
    if (acc11 > pool_max) pool_max = acc11;

    output[n * 400 + oc * 25 + ph * 5 + pw] = pool_max;
}

torch::Tensor lenet5_stage1_forward(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias
) {
    int N = x.size(0);
    auto output = torch::empty({N, 6, 14, 14}, x.options());
    int total = N * 6 * 14 * 14;
    int threads = 256;
    int blocks = (total + threads - 1) / threads;
    lenet5_stage1_kernel<<<blocks, threads>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        N
    );
    return output;
}

torch::Tensor lenet5_stage2_forward(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias
) {
    int N = x.size(0);
    auto output = torch::empty({N, 16, 5, 5}, x.options());
    int total = N * 16 * 5 * 5;
    int threads = 256;
    int blocks = (total + threads - 1) / threads;
    lenet5_stage2_kernel<<<blocks, threads>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        N
    );
    return output;
}
